#pragma once
// PulseDeck core: a bank of 200 ORIGINAL sounds generated by code.
// No samples from any third-party plugin are used or embedded.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

namespace pd
{
constexpr double kPi = 3.14159265358979323846;
constexpr double kTwoPi = 2.0 * kPi;
constexpr double kBankRate = 44100.0;
constexpr double kRootHz = 261.6255653; // C4
constexpr int kRootNote = 60;
constexpr int kNumCategories = 10;
constexpr int kVariants = 20;
constexpr int kNumSounds = kNumCategories * kVariants;

class Rng
{
public:
    explicit Rng (uint32_t seed) : s (seed ? seed : 0x9E3779B9u) {}
    uint32_t next() { s ^= s << 13; s ^= s >> 17; s ^= s << 5; return s; }
    float uni() { return (float) (next() >> 8) * (1.0f / 16777216.0f); }
    float bi() { return uni() * 2.0f - 1.0f; }
    float range (float a, float b) { return a + (b - a) * uni(); }
private:
    uint32_t s;
};

inline const char* categoryName (int c)
{
    static const char* names[kNumCategories] = { "Pluck", "Bell", "EPiano", "Pad", "Bass",
                                                 "Lead", "Mallet", "Kick", "Texture", "Choir" };
    return names[std::clamp (c, 0, kNumCategories - 1)];
}

inline std::string soundName (int idx)
{
    char buf[48];
    std::snprintf (buf, sizeof buf, "%s %02d", categoryName (idx / kVariants), idx % kVariants + 1);
    return buf;
}

namespace gen
{
using Buf = std::vector<float>;

inline int samples (float seconds) { return (int) (seconds * (float) kBankRate); }
inline float decayMul (float tau) { return std::exp (-1.0f / (tau * (float) kBankRate)); }

// Karplus-Strong plucked string
inline Buf pluck (Rng& r)
{
    const int n = samples (r.range (1.3f, 2.3f));
    const float damp = r.range (0.35f, 0.5f);
    const float decay = r.range (0.990f, 0.9985f);
    const float bright = r.range (0.2f, 1.0f);
    const int D = (int) std::lround (kBankRate / kRootHz - damp);
    std::vector<float> line ((size_t) D);
    float prev = 0.0f;
    for (auto& x : line) { prev += bright * (r.bi() - prev); x = prev; }
    Buf out ((size_t) n);
    int idx = 0;
    for (int i = 0; i < n; ++i)
    {
        const float cur = line[(size_t) idx];
        const float nxt = line[(size_t) ((idx + 1) % D)];
        line[(size_t) idx] = decay * ((1.0f - damp) * cur + damp * nxt);
        out[(size_t) i] = cur;
        idx = (idx + 1) % D;
    }
    return out;
}

// inharmonic additive bell
inline Buf bell (Rng& r)
{
    const int n = samples (r.range (2.0f, 3.0f));
    static const float base[8] = { 1.0f, 2.0f, 2.4f, 3.0f, 4.2f, 5.4f, 6.8f, 8.9f };
    const float baseTau = r.range (0.6f, 1.4f);
    const float stretch = r.range (0.0f, 0.04f);
    Buf out ((size_t) n, 0.0f);
    for (int k = 0; k < 8; ++k)
    {
        const double ratio = base[k] * (k == 0 ? 1.0 : 1.0 + stretch * k + 0.02 * r.bi());
        const float amp = (k == 0 ? 1.0f : r.range (0.2f, 0.9f)) / (1.0f + 0.35f * (float) k);
        const float tau = baseTau / (1.0f + 0.55f * (float) k);
        const double w = kTwoPi * kRootHz * ratio / kBankRate;
        const float m = decayMul (tau);
        float e = amp;
        double ph = 0.0;
        for (int i = 0; i < n; ++i) { out[(size_t) i] += e * (float) std::sin (ph); ph += w; e *= m; }
    }
    return out;
}

// 2-operator FM electric piano
inline Buf epiano (Rng& r)
{
    const int n = samples (r.range (1.6f, 2.6f));
    static const float ratios[6] = { 1.0f, 2.0f, 3.0f, 4.0f, 7.0f, 14.0f };
    const double ratio = ratios[r.next() % 6];
    const float index0 = r.range (1.0f, 5.0f);
    const float im = decayMul (r.range (0.12f, 0.6f));
    const float am = decayMul (r.range (0.7f, 1.8f));
    const double wc = kTwoPi * kRootHz / kBankRate, wm = wc * ratio;
    float ie = index0, ae = 1.0f;
    double pc = 0.0, pm = 0.0;
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        out[(size_t) i] = ae * (float) std::sin (pc + (double) ie * std::sin (pm));
        pc += wc; pm += wm; ie *= im; ae *= am;
    }
    for (int i = 0; i < std::min (n, 88); ++i) out[(size_t) i] *= (float) i / 88.0f;
    return out;
}

// detuned saw pad with slow filter movement
inline Buf pad (Rng& r)
{
    const float seconds = r.range (2.6f, 3.4f);
    const int n = samples (seconds);
    const int voices = 3 + (int) (r.next() % 3);
    const float spread = r.range (6.0f, 18.0f);
    const float att = r.range (0.25f, 0.9f);
    const float lp = r.range (0.03f, 0.18f);
    const double lfoRate = r.range (0.15f, 0.7f);
    double ph[5], inc[5];
    for (int v = 0; v < voices; ++v)
    {
        const double cents = spread * ((double) v / (double) (voices - 1) * 2.0 - 1.0);
        inc[v] = kRootHz * std::pow (2.0, cents / 1200.0) / kBankRate;
        ph[v] = r.uni();
    }
    Buf out ((size_t) n);
    float z1 = 0.0f, z2 = 0.0f;
    for (int i = 0; i < n; ++i)
    {
        const float t = (float) i / (float) kBankRate;
        float s = 0.0f;
        for (int v = 0; v < voices; ++v)
        {
            s += (float) (2.0 * (ph[v] - std::floor (ph[v])) - 1.0);
            ph[v] += inc[v];
        }
        s /= (float) voices;
        const float a = lp * (0.6f + 0.4f * (float) std::sin (kTwoPi * lfoRate * t));
        z1 += a * (s - z1);
        z2 += a * (z1 - z2);
        float e = std::min (1.0f, t / att);
        e = e * e * (3.0f - 2.0f * e);
        if (t > seconds - 0.7f) e *= std::max (0.0f, (seconds - t) / 0.7f);
        out[(size_t) i] = z2 * e;
    }
    return out;
}

// saturated sine bass
inline Buf bass (Rng& r)
{
    const int n = samples (r.range (0.9f, 1.6f));
    const float m = decayMul (r.range (0.25f, 0.8f));
    const float drv = r.range (1.0f, 6.0f);
    const float harm = r.range (0.0f, 0.5f);
    const double w = kTwoPi * kRootHz / kBankRate;
    double ph = 0.0;
    float e = 1.0f;
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        const float s = std::tanh (drv * (float) (std::sin (ph) + harm * std::sin (2.0 * ph)));
        out[(size_t) i] = e * s * std::min (1.0f, (float) i / 132.0f);
        ph += w; e *= m;
    }
    return out;
}

// PWM lead with vibrato
inline Buf lead (Rng& r)
{
    const int n = samples (r.range (1.2f, 2.0f));
    const double d1 = std::pow (2.0, r.range (3.0f, 14.0f) / 2400.0), d2 = 1.0 / d1;
    const double vibRate = r.range (4.5f, 6.5f), vibDepth = r.range (0.0f, 0.006f);
    const double pwmRate = r.range (0.2f, 1.5f);
    const float m = decayMul (r.range (0.5f, 1.4f));
    const float a = r.range (0.12f, 0.5f);
    double p1 = 0.0, p2 = r.uni();
    float e = 1.0f, z1 = 0.0f, z2 = 0.0f;
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        const double t = (double) i / kBankRate;
        const double vib = 1.0 + vibDepth * std::sin (kTwoPi * vibRate * t) * std::min (1.0, t / 0.3);
        const double pw = 0.5 + 0.35 * std::sin (kTwoPi * pwmRate * t);
        const float s = 0.5f * ((p1 < pw ? 1.0f : -1.0f) + (p2 < 1.0 - pw ? 1.0f : -1.0f));
        p1 += kRootHz * vib * d1 / kBankRate; p1 -= std::floor (p1);
        p2 += kRootHz * vib * d2 / kBankRate; p2 -= std::floor (p2);
        z1 += a * (s - z1);
        z2 += a * (z1 - z2);
        out[(size_t) i] = z2 * e * std::min (1.0f, (float) i / 350.0f);
        e *= m;
    }
    return out;
}

// marimba-like mallet
inline Buf mallet (Rng& r)
{
    const int n = samples (r.range (0.9f, 1.5f));
    const float t1 = r.range (0.25f, 0.6f);
    const float ratios[3] = { 1.0f, 3.9f + r.range (-0.2f, 0.2f), 9.2f + r.range (-0.4f, 0.4f) };
    const float taus[3] = { t1, t1 * 0.3f, t1 * 0.1f };
    const float amps[3] = { 1.0f, r.range (0.3f, 0.8f), r.range (0.1f, 0.4f) };
    const float click = r.range (0.1f, 0.5f);
    Buf out ((size_t) n, 0.0f);
    for (int k = 0; k < 3; ++k)
    {
        const double w = kTwoPi * kRootHz * ratios[k] / kBankRate;
        const float m = decayMul (taus[k]);
        float e = amps[k];
        double ph = 0.0;
        for (int i = 0; i < n; ++i) { out[(size_t) i] += e * (float) std::sin (ph); ph += w; e *= m; }
    }
    for (int i = 0; i < std::min (n, 100); ++i) out[(size_t) i] += click * r.bi() * (1.0f - (float) i / 100.0f);
    return out;
}

// pitch-dropping kick / tonal hit
inline Buf kick (Rng& r)
{
    const int n = samples (r.range (0.5f, 0.9f));
    const float startHz = r.range (110.0f, 300.0f), endHz = r.range (48.0f, 75.0f);
    const float pm = decayMul (r.range (0.015f, 0.06f));
    const float am = decayMul (r.range (0.16f, 0.4f));
    const float click = r.range (0.1f, 0.6f), drv = r.range (1.0f, 3.0f);
    double ph = 0.0;
    float fe = 1.0f, ae = 1.0f;
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        const float f = endHz + (startHz - endHz) * fe;
        ph += kTwoPi * (double) f / kBankRate;
        float s = ae * std::tanh (drv * (float) std::sin (ph));
        if (i < 100) s += click * r.bi() * (1.0f - (float) i / 100.0f);
        out[(size_t) i] = s;
        fe *= pm; ae *= am;
    }
    return out;
}

// moving filtered-noise swell with a faint tone
inline Buf texture (Rng& r)
{
    const float seconds = r.range (2.4f, 3.4f);
    const int n = samples (seconds);
    const double lfoRate = r.range (0.2f, 1.2f), lfoPh = r.uni() * kTwoPi;
    const float base = r.range (0.01f, 0.04f), span = r.range (0.05f, 0.3f);
    const float toneAmt = r.range (0.0f, 0.4f);
    static const float ratios[4] = { 1.0f, 1.5f, 2.0f, 3.0f };
    const double w = kTwoPi * kRootHz * ratios[r.next() % 4] / kBankRate;
    double ph = 0.0;
    float z1 = 0.0f, z2 = 0.0f, z3 = 0.0f;
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        const double t = (double) i / kBankRate;
        const float a = base + span * (0.5f + 0.5f * (float) std::sin (kTwoPi * lfoRate * t + lfoPh));
        z1 += a * (r.bi() - z1); z2 += a * (z1 - z2); z3 += a * (z2 - z3);
        const float s = z3 * (0.4f / std::sqrt (a)) + toneAmt * (float) std::sin (ph);
        ph += w;
        const float x = (float) (t / seconds);
        const float e = std::sin ((float) kPi * x);
        out[(size_t) i] = s * e * e;
    }
    return out;
}

// additive formant "choir"
inline Buf choir (Rng& r)
{
    static const float F[5][2] = { { 800, 1150 }, { 400, 1600 }, { 350, 2300 }, { 450, 800 }, { 325, 700 } };
    const int vow = (int) (r.next() % 5);
    const float f1 = F[vow][0] * r.range (0.9f, 1.1f), f2 = F[vow][1] * r.range (0.9f, 1.1f);
    const float seconds = r.range (2.4f, 3.4f);
    const int n = samples (seconds);
    const int H = (int) (6000.0 / kRootHz);
    std::vector<int> hs; std::vector<float> ws;
    for (int h = 1; h <= H; ++h)
    {
        const float fh = (float) (h * kRootHz);
        const float a = (fh - f1) / 220.0f, b = (fh - f2) / 350.0f;
        const float w = std::exp (-a * a) + 0.7f * std::exp (-b * b) + 0.08f / (float) h;
        if (w > 0.03f) { hs.push_back (h); ws.push_back (w); }
    }
    const double cents = r.range (4.0f, 10.0f);
    const double inc[2] = { kRootHz * std::pow (2.0, -cents / 1200.0) / kBankRate,
                            kRootHz * std::pow (2.0, cents / 1200.0) / kBankRate };
    double ph[2] = { (double) r.uni(), (double) r.uni() };
    const double vibRate = r.range (4.8f, 6.0f);
    Buf out ((size_t) n);
    for (int i = 0; i < n; ++i)
    {
        const float t = (float) i / (float) kBankRate;
        const double vib = 1.0 + 0.004 * std::sin (kTwoPi * vibRate * t) * std::min (1.0f, t / 0.5f);
        float s = 0.0f;
        for (int v = 0; v < 2; ++v)
        {
            for (size_t k = 0; k < hs.size(); ++k)
                s += ws[k] * (float) std::sin ((double) hs[k] * kTwoPi * ph[v]);
            ph[v] += inc[v] * vib; ph[v] -= std::floor (ph[v]);
        }
        float e = std::min (1.0f, t / 0.3f);
        e = e * e * (3.0f - 2.0f * e);
        if (t > seconds - 0.7f) e *= std::max (0.0f, (seconds - t) / 0.7f);
        out[(size_t) i] = s * e;
    }
    return out;
}

inline void finalize (Buf& b)
{
    float peak = 0.0f;
    for (auto& x : b) { if (! std::isfinite (x)) x = 0.0f; peak = std::max (peak, std::fabs (x)); }
    if (peak > 1e-9f) { const float g = 0.9f / peak; for (auto& x : b) x *= g; }
    const int fade = std::min ((int) b.size(), (int) (0.015 * kBankRate));
    for (int i = 0; i < fade; ++i)
        b[b.size() - 1 - (size_t) i] *= 0.5f - 0.5f * (float) std::cos (kPi * (double) i / (double) fade);
}

inline Buf generate (int idx)
{
    idx = std::clamp (idx, 0, kNumSounds - 1);
    Rng r (0x9E3779B9u * (uint32_t) (idx + 1) + 12345u);
    for (int i = 0; i < 4; ++i) r.next();
    Buf b;
    switch (idx / kVariants)
    {
        case 0: b = pluck (r); break;
        case 1: b = bell (r); break;
        case 2: b = epiano (r); break;
        case 3: b = pad (r); break;
        case 4: b = bass (r); break;
        case 5: b = lead (r); break;
        case 6: b = mallet (r); break;
        case 7: b = kick (r); break;
        case 8: b = texture (r); break;
        default: b = choir (r); break;
    }
    finalize (b);
    return b;
}
} // namespace gen

class SoundBank
{
public:
    SoundBank()
    {
        sounds.reserve (kNumSounds);
        for (int i = 0; i < kNumSounds; ++i) sounds.push_back (gen::generate (i));
    }
    const std::vector<float>& get (int i) const { return sounds[(size_t) std::clamp (i, 0, kNumSounds - 1)]; }
private:
    std::vector<std::vector<float>> sounds;
};
} // namespace pd
